import{_ as t,c as r,o,a5 as a}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"系统架构","description":"","frontmatter":{"title":"系统架构","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#1.2","branch":"main","level":1,"order":1.2},"headers":[],"relativePath":"posts/projects/zfeed/01-zfeed-overview/02-system-architecture.md","filePath":"posts/projects/zfeed/01-zfeed-overview/02-system-architecture.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/01-zfeed-overview/02-system-architecture.md"};function i(l,e,n,p,d,b){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1" target="_blank" rel="noreferrer">README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/front/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/etc/content.yaml" target="_blank" rel="noreferrer">app/rpc/content/etc/content.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/consts/redis/redis_consts.go" target="_blank" rel="noreferrer">app/rpc/content/internal/common/consts/redis/redis_consts.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_follow_inbox_zset.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_follow_inbox_zset.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/redis_lua.go" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/redis_lua.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/content/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/article_repository.go" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/article_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/content_repository.go" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/content_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/repositories/video_repository.go" target="_blank" rel="noreferrer">app/rpc/content/internal/repositories/video_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/content/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env" target="_blank" rel="noreferrer">deploy/.env</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/README.md?plain=1" target="_blank" rel="noreferrer">deploy/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml" target="_blank" rel="noreferrer">deploy/docker-compose.yml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf" target="_blank" rel="noreferrer">deploy/nginx/default.conf</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.mod" target="_blank" rel="noreferrer">go.mod</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.sum" target="_blank" rel="noreferrer">go.sum</a></li></ul></details><p><code>zfeed</code> 系统基于 go-zero 框架构建，采用微服务架构。它把内容社区平台拆分为六个专门服务，这些服务通过高性能 gRPC 交互，使用 Etcd 做服务发现，并依赖一组基础设施组件完成数据持久化、缓存和事件驱动处理。</p><h2 id="微服务拓扑" tabindex="-1">微服务拓扑 <a class="header-anchor" href="#微服务拓扑" aria-label="Permalink to &quot;微服务拓扑&quot;">​</a></h2><p>系统包含一个统一入口 API 网关和五个后端 RPC 服务。服务间通信严格基于 gRPC，网关则向客户端暴露 RESTful HTTP 接口。</p><h3 id="服务概览" tabindex="-1">服务概览 <a class="header-anchor" href="#服务概览" aria-label="Permalink to &quot;服务概览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>职责</th><th>端口</th></tr></thead><tbody><tr><td><code>front-api</code></td><td>HTTP 入口、认证、请求聚合。</td><td><code>5000</code></td></tr><tr><td><code>user-rpc</code></td><td>用户生命周期、会话管理和个人资料数据。</td><td><code>5003</code></td></tr><tr><td><code>content-rpc</code></td><td>内容发布、Feed 生成和热门内容排序。</td><td><code>5001</code></td></tr><tr><td><code>interaction-rpc</code></td><td>社交动作（点赞、评论、关注）和事件 outbox。</td><td><code>5002</code></td></tr><tr><td><code>count-rpc</code></td><td>高频计数器管理和 CDC 事件消费。</td><td><code>5004</code></td></tr><tr><td><code>search-rpc</code></td><td>面向用户和内容的全文搜索，并提供稳定分页。</td><td><code>5006</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L23-L30" target="_blank" rel="noreferrer">README.md#23-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L19-L25" target="_blank" rel="noreferrer">deploy/.env#19-25</a></p><h3 id="服务通信与发现" tabindex="-1">服务通信与发现 <a class="header-anchor" href="#服务通信与发现" aria-label="Permalink to &quot;服务通信与发现&quot;">​</a></h3><p>所有 RPC 服务都会注册到 Etcd。客户端（包括 <code>front-api</code> 和其他 RPC 服务）使用 Etcd 作为服务发现后端，动态定位目标服务实例。</p><ul><li>注册：服务将自己的监听地址（例如 <code>CONTENT_RPC_LISTEN_ON</code>）注册到 Etcd 中的特定 key 下，例如 <code>content.rpc</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L33-L36" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#33-36</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L21-L25" target="_blank" rel="noreferrer">deploy/.env#21-25</a></li><li>发现：客户端配置中定义 <code>Etcd</code> 主机和 key，用于动态解析服务端点。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L38-L43" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#38-43</a></li><li>服务间调用：服务经常相互调用以聚合数据。例如 <code>content-rpc</code> 的 <code>GetContentDetail</code> 会并发调用 <code>user-rpc</code>、<code>count-rpc</code> 和 <code>interaction-rpc</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L180-L212" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#180-212</a></li></ul><h2 id="基础设施组件" tabindex="-1">基础设施组件 <a class="header-anchor" href="#基础设施组件" aria-label="Permalink to &quot;基础设施组件&quot;">​</a></h2><p>系统依赖 <code>docker-compose.yml</code> 环境中定义的标准化基础设施栈。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L1-L350" target="_blank" rel="noreferrer">deploy/docker-compose.yml#1-350</a></p><table tabindex="0"><thead><tr><th>组件</th><th>在 zfeed 中的作用</th></tr></thead><tbody><tr><td>MySQL</td><td>用户、内容和交互日志的主要持久化存储。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L71-L77" target="_blank" rel="noreferrer">deploy/.env#71-77</a></td></tr><tr><td>Redis</td><td>会话存储、热门 Feed 缓存、分布式锁，以及基于 Lua 的原子操作。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L67-L70" target="_blank" rel="noreferrer">deploy/.env#67-70</a></td></tr><tr><td>Kafka</td><td>交互事件和 Canal binlog 数据的消息代理。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L79-L85" target="_blank" rel="noreferrer">deploy/.env#79-85</a></td></tr><tr><td>Canal</td><td>CDC（Change Data Capture）工具，用于监听 MySQL binlog 并将更新流式发送到 Kafka。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L97-L100" target="_blank" rel="noreferrer">deploy/.env#97-100</a></td></tr><tr><td>Etcd</td><td>服务发现与配置管理。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L61-L66" target="_blank" rel="noreferrer">deploy/.env#61-66</a></td></tr><tr><td>XXL-JOB</td><td>分布式任务调度，用于热门内容排序等周期性任务。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L86-L96" target="_blank" rel="noreferrer">deploy/.env#86-96</a></td></tr></tbody></table><h2 id="数据流与架构图" tabindex="-1">数据流与架构图 <a class="header-anchor" href="#数据流与架构图" aria-label="Permalink to &quot;数据流与架构图&quot;">​</a></h2><h3 id="请求路径-内容信息增强" tabindex="-1">请求路径：内容信息增强 <a class="header-anchor" href="#请求路径-内容信息增强" aria-label="Permalink to &quot;请求路径：内容信息增强&quot;">​</a></h3><p>该图展示 <code>front-api</code> 如何将请求路由到 <code>content-rpc</code>，再由 <code>content-rpc</code> 编排多个内部调用，构建完整的 <code>ContentDetail</code> 对象。</p><p>标题：内容详情聚合流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L113-L134" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#113-134</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L180-L212" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#180-212</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L57-L70" target="_blank" rel="noreferrer">deploy/nginx/default.conf#57-70</a></p><h3 id="事件驱动计数路径" tabindex="-1">事件驱动计数路径 <a class="header-anchor" href="#事件驱动计数路径" aria-label="Permalink to &quot;事件驱动计数路径&quot;">​</a></h3><p>该图展示交互事件（例如“点赞”）如何从数据库出发，经由 Canal 和 Kafka 异步流转到计数服务。</p><p>标题：CDC 与异步计数流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L5-L30" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#5-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L133-L150" target="_blank" rel="noreferrer">deploy/docker-compose.yml#133-150</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L28-L29" target="_blank" rel="noreferrer">README.md#28-29</a></p><h2 id="技术实现细节" tabindex="-1">技术实现细节 <a class="header-anchor" href="#技术实现细节" aria-label="Permalink to &quot;技术实现细节&quot;">​</a></h2><h3 id="配置管理" tabindex="-1">配置管理 <a class="header-anchor" href="#配置管理" aria-label="Permalink to &quot;配置管理&quot;">​</a></h3><p>服务使用 <code>.yaml</code> 文件，并通过 go-zero 的 <code>conf.Load</code> 支持环境变量展开。这使同一个二进制文件可以在不同环境（Dev、Test、Prod）中借助 <code>deploy/.env</code> 文件加载不同配置。</p><ul><li>文件路径：<code>app/rpc/search/etc/search.yaml</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L1-L61" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#1-61</a></li><li>测试校验：<code>TestSearchConfigLoadsWithEnv</code> 确保 <code>SEARCH_RPC_LISTEN_ON</code>、<code>MYSQL_HOST</code> 等变量能正确映射到 <code>Config</code> 结构体。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go#L9-L63" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go#9-63</a></li></ul><h3 id="可观测性" tabindex="-1">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h3><p>系统集成了一整套可观测性能力：</p><ol><li>指标：为搜索延迟、缓存命中率和请求总量定义自定义 Prometheus 直方图与计数器。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L29-L71" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#29-71</a></li><li>链路追踪：OpenTelemetry（OTEL）采集器收集所有服务的 trace，并在 Jaeger 中可视化。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L51-L59" target="_blank" rel="noreferrer">deploy/.env#51-59</a></li><li>日志：各服务输出结构化 JSON 日志，并存储在 <code>/var/log/zfeed</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L16-L32" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#16-32</a></li></ol><h3 id="搜索架构" tabindex="-1">搜索架构 <a class="header-anchor" href="#搜索架构" aria-label="Permalink to &quot;搜索架构&quot;">​</a></h3><p><code>search-rpc</code> 服务实现多层缓存策略，用于处理复杂的全文搜索查询：</p><ul><li>查询缓存：存储高频关键词的页面级结果。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L13-L21" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#13-21</a></li><li>文档缓存：缓存单个实体摘要。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L20-L20" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#20</a></li><li>快照系统：通过在 Redis 中按指定 TTL 冻结结果集，提供稳定分页。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L139-L141" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#139-141</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L128-L159" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#128-159</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L8-L22" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#8-22</a></p>',34)])])}const s=t(c,[["render",i]]);export{f as __pageData,s as default};
